def max_product(num_str: str, N: int, K: int) -> int:
    n = len(num_str)
    memo = [[0] * (K + 1) for _ in range(n)]

    for k in range(1, K + 1):
        for left in range(n - k + 1):
            right = left + k
            for mid in range(left, right):
                left_sum = int(num_str[left:mid]) if left < mid else 0
                right_sum = int(num_str[mid:right]) if mid < right else 0

                if left_sum >= right_sum:
                    memo[left][k] = max(memo[left][k], memo[left][k - 1] * left_sum + max_product(num_str[mid:right], n - mid, k - 1))
                else:
                    memo[left][k] = max(memo[left][k], memo[left][k - 1] * right_sum + max_product(num_str[left:mid], n - mid, k - 1))

    return memo[0][K]
