def count_passing_ways(n: int, m: int) -> int:
    # Base case: if there are no students, or m passes, there is a single way
    if n == 0 or m == 0:
        return 1

    # Initialize a table to store the number of ways
    dp = [[0 for _ in range(m + 1)] for _ in range(n + 1)]

    # Set up the first row and first column
    for i in range(n + 1):
        dp[i][0] = 1
    for j in range(m + 1):
        dp[0][j] = 0

    # Fill the dynamic programming table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = dp[i - 1][j - 1] + dp[i - 2][j - 1]

    # The result is the number of ways after n-1 passes
    return dp[n][m]
