    # Define the dimensions of the DP table
    dp = [[0 for _ in range(m + 1)] for _ in range(n)]

    # Initialize the base cases
    for i in range(n):
        dp[i][0] = 1  # The ball returns to the starting student after 0 passes
        if i == 0 or i == n - 1:
            dp[i][1] = 1  # If it's the first or last student, the ball never leaves the circle after a single pass

    # Fill the DP table based on the transitions
    for i in range(2, m + 1):
        for j in range(1, n):
            if j == 0 or j == n - 1:
                dp[j][i] = dp[n - 1][i - 1] + dp[1][i - 1]  # If on the boundary, the ball can pass either way
            else:
                dp[j][i] = dp[j - 1][i - 1] + dp[(j + 1) % n][i - 1]  # Otherwise, it can pass to either neighbor

    # The result is the number of ways the ball returns to the starting student after m passes
    return dp[0][m]
