        '100x^5-x^4+x^3-3x^2+10'

        >>> polynomial_to_string(3, [-50, 0, 0, 1])
        '-50x^3+1'
    """
    result = ""
    for i in range(n, -1, -1):
        coeff = coeffs[i]
        if coeff == 0:
            continue
        if i == 0:
            if coeff != 1:
                result += str(coeff)
        elif i == 1:
            if coeff == 1:
                result += "x"
            else:
                result += "{}x".format(coeff)
        else:
            if coeff == 1:
                result += "x^{}".format(i)
            else:
                result += "{}x^{}".format(coeff, i)
            if i > 1:
                result += "+"
    return result
