def max_herb_value(T, M, herbs):
    # Initialize a 2D array to store the maximum value for each subproblem
    dp = [[0] * (T + 1)] * (M + 1)

    # Fill the dp table using dynamic programming
    for j in range(1, M + 1):
        for i in range(1, T + 1):
            if herbs[j - 1][0] <= i:
                dp[j][i] = max(dp[j - 1][i], dp[j - 1][i - herbs[j - 1][0]] + herbs[j - 1][1])
            else:
                dp[j][i] = dp[j - 1][i]

    # The maximum possible value of herbs is stored in dp[M][T]
    return dp[M][T]
