    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = (dp[i - 1][j] + (a[i - 1] * dp[i][j - 1]) % MOD) % MOD
            if j - a[i - 1] >= 0:
                dp[i][j] = (dp[i][j] - dp[i][j - a[i - 1]] + MOD) % MOD

    return dp[n][m]
