def vigenere_decrypt(key, ciphertext):
    def shift_char(c, shift):
        if c.islower():
            return chr((ord(c) - ord('a') - shift) % 26 + ord('a'))
        elif c.isupper():
            return chr((ord(c) - ord('A') - shift) % 26 + ord('A'))
        else:
            return c

    plaintext = ''
    key_index = 0
    for ch in ciphertext:
        if ch.isalpha():
            shift = ord(key[key_index % len(key)]) - ord('A')
            plaintext += shift_char(ch, -shift)
            key_index += 1
        else:
            plaintext += ch
    return plaintext
