def next_permutation(perm: list) -> bool:
    # Find the first index from the right where the current element is smaller than the preceding element.
    for i in range(len(perm) - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            # Find the smallest element in the sublist starting from i+1 that is greater than perm[i].
            for j in range(len(perm) - 1, i, -1):
                if perm[j] > perm[i]:
                    # Swap the elements at index i and j.
                    perm[i], perm[j] = perm[j], perm[i]
                    # Reverse the sublist from i+1 to the end to place the larger elements in decreasing order.
                    perm[i+1:] = perm[i+1:][::-1]
                    return True
    # If no such element is found, the input is already in the last permutation.
    return False
```

