def min_groups(w, n, prices):
    # Initialize the recursive function with 0 souvenirs seen so far
    def min_groups_recursive(n, w, start_index):
        # Base case 1: If there are no more souvenirs to consider, no more groups are needed
        if n == 0:
            return 0

        # Base case 2: If the current group exceeds the price limit, move to the next group without adding any souvenirs
        if prices[start_index] > w:
            return min_groups_recursive(n, w, start_index + 1)

        # Include one souvenir in the current group and try to minimize the recursive call
        include = 1 + min_groups_recursive(n - 1, w - prices[start_index], start_index + 1)

        # Exclude the current souvenir and try to minimize the recursive call
        exclude = min_groups_recursive(n, w, start_index + 1)

        # Return the minimum of including or excluding the current souvenir
        return min(include, exclude)

    # Start the recursive function with all souvenirs and the maximum allowed price
    return min_groups_recursive(n, w, 0)
```

